var flowers = [];

var PHI = (1 + Math.sqrt(5)) / 2;
var angles = [];
var angleNames = [];

function setup() {
  colorMode(HSB);
  createCanvas(800, 600);
  background(0);
  angleMode(DEGREES);
  noStroke();

  // Winkelwerte
  angles = [
    random(1, 5), PHI, PI, Math.sqrt(2), Math.sqrt(3), random(1, 5),
    Math.E, Math.sqrt(5), Math.log(2), PHI * PHI, 1 / PHI
  ];

  angleNames = [
    "Random A", "Golden Ratio φ", "Pi π", "√2", "√3", "Random B",
    "Euler e", "√5", "log(2)", "φ²", "1/φ"
  ];

  let flowerColor = color(60, 255, 255); // Einheitliche Farbe

  // Große Blumen
  for (let i = 0; i < 6; i++) {
    var x = 60 + i * 140;
    var y = height / 2;
    let petalCount = floor(random(15, 20));
    flowers.push(new Flower(x, y, petalCount, flowerColor, 50, angles[i], angleNames[i]));
  }

  // Kleine Blumen
  for (let i = 0; i < 5; i++) {
    var x = 130 + i * 140;
    var y = height / 2 + 100;
    var petalCount = floor(random(10, 14));
    flowers.push(new Flower(x, y, petalCount, flowerColor, 20, angles[i + 6], angleNames[i + 6]));
  }
}

function draw() {
  background(0);
  let hovering = false;

  for (let flower of flowers) {
    flower.display();
    flower.showAngle();

    if (
      flower.doneGrowing &&
      dist((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))), flower.x, flower.y) < flower.centralRadius * flower.growth
    ) {
      hovering = true;
    }
  }

  cursor(hovering ? HAND : ARROW);
}
